function exportElement(print = false) {
    const element = document.getElementById('sb-print-document');
    if (!element)
        return;
    const html = `<!doctype html><html lang="nl"><head><meta charset="utf-8"><title>Duindorp SV · Sponsorovereenkomst</title><style>body{font:13px/1.8 Arial,sans-serif;color:#234564;max-width:800px;margin:40px auto;padding:20px}h3,h4{color:#075098}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:9px;border-bottom:1px solid #dee6ef}img{max-width:90px;max-height:80px}.sb-document-header{display:flex;justify-content:space-between;border-bottom:3px solid #075098;padding-bottom:20px}.sb-total{margin:20px 0;padding:14px;background:#f3f7fb}.sb-total>div{display:flex;justify-content:space-between;padding:4px}.sb-signature-box{border:1px solid #cfe1d6;padding:17px;margin-top:20px;background:#f2f8f4}.sb-signature-box small{display:block}small{color:#71869b}p{white-space:pre-wrap}@page{size:A4;margin:16mm}@media print{body{margin:0;padding:0}}</style></head><body>${element.innerHTML.replaceAll('src="/', 'src="' + window.location.origin + '/')}</body></html>`;
    if (print) {
        const target = window.open('', '_blank', 'noopener=false');
        if (target) {
            target.addEventListener('load', () => target.print(), { once: true });
            target.document.write(html);
            target.document.close();
        }
        return;
    }
    const url = URL.createObjectURL(new Blob([html], { type: 'text/html;charset=utf-8' }));
    const link = document.createElement('a');
    link.href = url;
    link.download = 'Duindorp-SV-sponsordocument.html';
    link.click();
    setTimeout(() => URL.revokeObjectURL(url), 1000);
}
