function BusinessReadiness({ sponsor }: {
    sponsor: Sponsor;
}) { const value = getSponsorBusinessReadiness(sponsor); return <div className={`sb-business-readiness ${value.complete && value.confirmed ? 'ready' : ''}`}><ShieldCheck size={18}/><div><strong>{value.complete && value.confirmed ? 'Bedrijfsgegevens gecontroleerd' : 'Bedrijfsgegevens nog controleren'}</strong><p>{value.complete ? value.confirmed ? 'Dit dossier is klaar voor nieuwe overeenkomsten.' : 'Alle verplichte gegevens zijn ingevuld. De sponsorcommissie moet het dossier nog bevestigen.' : `Nog nodig: ${value.missing.join(' · ')}`}</p></div>{value.complete && value.confirmed && <CheckCircle2 size={18}/>}</div>; }
const ClockIcon = CalendarDays;
